import React, { useState, useEffect } from 'react';

export default function Dashboard({ token }) {
  const [cameras, setCameras] = useState([]);
  const [userEmail, setUserEmail] = useState('');
  const [emailSavedMsg, setEmailSavedMsg] = useState('');

  useEffect(() => {
    // Request Browser Notification Permission
    if ('Notification' in window && Notification.permission !== 'granted') {
      Notification.requestPermission();
    }

    // Fetch setup camera streams
    fetch('http://localhost:5000/api/cameras', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setCameras(data))
      .catch(err => console.error(err));

    // Fetch current alert email
    fetch('http://localhost:5000/api/settings', {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => setUserEmail(data.email || ''))
      .catch(err => console.error(err));
  }, [token]);

  const handleSaveEmail = (e) => {
    e.preventDefault();
    fetch('http://localhost:5000/api/settings', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify({ email: userEmail })
    })
      .then(res => res.json())
      .then(data => {
        setEmailSavedMsg('Alert recipient email updated!');
        setTimeout(() => setEmailSavedMsg(''), 3000);
      });
  };

  const handleDeleteCamera = (id) => {
    fetch(`http://localhost:5000/api/cameras/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(() => setCameras(cameras.filter(c => c.id !== id)));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>

      {/* EMAIL & NOTIFICATION SETTINGS CARD */}
      <div className="card" style={{ background: '#1e293b', borderLeft: '4px solid #38bdf8' }}>
        <h3>⚙️ Alert Notification Configuration</h3>
        <p style={{ color: '#94a3b8', fontSize: '0.9rem', margin: '0.5rem 0 1rem 0' }}>
          Specify your email address below to automatically receive security logs and live alerts.
        </p>

        {emailSavedMsg && <div className="message-banner success">{emailSavedMsg}</div>}

        <form onSubmit={handleSaveEmail} style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <div className="form-group" style={{ flex: 1, marginBottom: 0 }}>
            <input
              type="email"
              placeholder="enter.your.email@gmail.com"
              value={userEmail}
              onChange={e => setUserEmail(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="btn-primary" style={{ width: 'auto', marginTop: 0, padding: '0.75rem 1.5rem' }}>
            Save Email
          </button>
        </form>
      </div>

      {/* CAMERA STREAMS SECTION */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2>Connected Stream Feeds ({cameras.length})</h2>
          <span style={{ color: '#34d399', fontWeight: '600' }}>● AI Multi-Model Inference Active</span>
        </div>

        {cameras.length === 0 ? (
          <div className="card" style={{ marginTop: '1.5rem', textAlign: 'center', padding: '3rem' }}>
            <p style={{ color: '#94a3b8' }}>No active camera streams configured.</p>
            <p style={{ color: '#64748b', fontSize: '0.85rem', marginTop: '0.5rem' }}>
              Go to <strong>Add Camera</strong> and enter RTSP URL <strong>0</strong> to connect your built-in Laptop Camera!
            </p>
          </div>
        ) : (
          <div className="camera-grid">
            {cameras.map((cam) => (
              <div key={cam.id} className="card camera-card">
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <h3>{cam.name}</h3>
                  <span className="location-badge">{cam.locationType}</span>
                </div>
                <div className="feed-box">
                  <span className="live-tag">LIVE FEED</span>
                  <p style={{ color: '#94a3b8', fontSize: '0.85rem' }}>
                    {cam.rtspUrl === '0' ? '📷 Laptop Webcam (Index 0)' : `Stream: ${cam.rtspUrl}`}
                  </p>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.75rem' }}>
                  <p style={{ fontSize: '0.8rem', color: '#64748b' }}>RTSP Source: {cam.rtspUrl}</p>
                  <button
                    onClick={() => handleDeleteCamera(cam.id)}
                    style={{ background: 'none', border: 'none', color: '#f87171', cursor: 'pointer', fontSize: '0.8rem' }}
                  >
                    Remove Stream
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

    </div>
  );
}
